//! TypeScript wire declaration generation from directional JSON Schemas.

use serde_json::Value;
use std::collections::{BTreeMap, BTreeSet};

use super::{Direction, MethodEntry, MethodKind, Payload};

/// Repository-relative path of the generated declaration file.
pub const DECLARATION_PATH: &str = "clients/vscode/types/protocol.d.ts";

/// One generated TypeScript declaration file.
pub struct Declarations {
    /// Repository-relative output path.
    pub path: &'static str,
    /// Complete generated file text.
    pub text: String,
}

const HEADER: &str = concat!(
    "// Generated by scripts/generate_schema.rs from docs/schema/*.json.\n",
    "// Do not edit; run `make update-schema` to regenerate.\n",
    "//\n",
    "// Each namespace mirrors one directional schema root so that input and\n",
    "// output definitions with the same Rust name never collide.\n",
);

/// Generate the complete protocol declaration file from the directional
/// artifacts and the custom method catalog.
pub fn protocol_declarations() -> Result<Declarations, String> {
    let mut roots: BTreeMap<String, String> = BTreeMap::new();
    let mut body = String::new();
    for artifact in super::artifacts() {
        if artifact.file == "methods.json" || artifact.file == "shared-lists.json" {
            // The method catalog and shared capability lists are catalog data,
            // not payload schemas.
            continue;
        }
        let name = root_name(&artifact.schema)?;
        if roots
            .insert(artifact.file.to_string(), name.clone())
            .is_some()
        {
            return Err(format!("duplicate schema artifact {}", artifact.file));
        }
        body.push_str(&render_root(&artifact.schema, &name)?);
        body.push('\n');
    }
    let catalog = render_method_map(&super::methods(), &roots)?;
    Ok(Declarations {
        path: DECLARATION_PATH,
        text: format!("{HEADER}{body}{catalog}"),
    })
}

/// Render one directional root schema as a namespaced TypeScript declaration.
///
/// Local definitions live inside `namespace <name>` and are referenced
/// unqualified, which keeps same-named definitions from different roots apart.
pub fn render_root(schema: &Value, name: &str) -> Result<String, String> {
    validate_identifier(name)?;
    let mut out = String::new();
    out.push_str(&format!("export namespace {name} {{\n"));
    if let Some(doc) = doc_comment(schema, 2) {
        out.push_str(&doc);
    }
    let mut root = schema.clone();
    if let Some(map) = root.as_object_mut() {
        // Definitions are declared as sibling types inside the namespace.
        map.remove("$defs");
    }
    out.push_str(&format!("  export type Root = {};\n", type_expr(&root, 2)?));
    if let Some(defs) = schema.get("$defs") {
        let defs = defs
            .as_object()
            .ok_or_else(|| format!("{name}: $defs must be an object"))?;
        let sorted: BTreeMap<&String, &Value> = defs.iter().collect();
        for (def_name, definition) in sorted {
            validate_identifier(def_name)?;
            out.push('\n');
            if let Some(doc) = doc_comment(definition, 2) {
                out.push_str(&doc);
            }
            out.push_str(&format!(
                "  export type {def_name} = {};\n",
                type_expr(definition, 2)?
            ));
        }
    }
    out.push_str("}\n");
    Ok(out)
}

/// Name of the root type declared by one schema artifact.
fn root_name(schema: &Value) -> Result<String, String> {
    let title = schema
        .get("title")
        .and_then(Value::as_str)
        .ok_or_else(|| "schema root is missing `title`".to_string())?;
    validate_identifier(title)?;
    Ok(title.to_string())
}

/// Render the catalog-based params/result mapping.
fn render_method_map(
    methods: &[MethodEntry],
    roots: &BTreeMap<String, String>,
) -> Result<String, String> {
    let mut out = String::from(
        "/** Custom protocol method catalog from docs/schema/methods.json. */\n\
         export interface MethodMap {\n",
    );
    for entry in methods {
        let kind = match entry.kind {
            MethodKind::Request => "request",
            MethodKind::Notification => "notification",
        };
        let direction = match entry.direction {
            Direction::Input => "clientToServer",
            Direction::Output => "serverToClient",
        };
        out.push_str(&format!(
            "  {}: {{\n    kind: \"{kind}\";\n    direction: \"{direction}\";\n    params: {};\n",
            // Method names are static catalog data; quote them as object keys.
            serde_json::to_string(entry.method).expect("method name serializes"),
            payload_type(&entry.params, roots)?
        ));
        if let Some(result) = &entry.result {
            out.push_str(&format!("    result: {};\n", payload_type(result, roots)?));
        }
        out.push_str("  };\n");
    }
    out.push_str("}\n\n");
    out.push_str("/// Any method name in the custom protocol catalog.\n");
    out.push_str("export type MethodName = keyof MethodMap;\n");
    Ok(out)
}

/// TypeScript type for one catalog payload reference.
fn payload_type(payload: &Payload, roots: &BTreeMap<String, String>) -> Result<String, String> {
    match payload {
        Payload::UnconstrainedJson => Ok("unknown".to_string()),
        Payload::Schema { file, .. } => {
            let name = roots
                .get(*file)
                .ok_or_else(|| format!("catalog references unknown schema artifact {file}"))?;
            Ok(format!("{name}.Root"))
        }
    }
}

/// Render one schema value as a TypeScript type expression.
fn type_expr(schema: &Value, indent: usize) -> Result<String, String> {
    match schema {
        Value::Bool(true) => Ok("unknown".to_string()),
        Value::Bool(false) => Ok("never".to_string()),
        Value::Object(map) => {
            validate_keys(map)?;
            if map.contains_key("$defs") {
                return Err("nested `$defs` is unsupported".to_string());
            }
            for key in ["oneOf", "anyOf", "allOf"] {
                if !map.contains_key(key) {
                    continue;
                }
                for dropped in ["const", "enum"] {
                    if map.contains_key(dropped) {
                        return Err(format!(
                            "`{dropped}` beside `{key}` is unsupported; sibling constraints would be dropped"
                        ));
                    }
                }
            }
            if let Some(reference) = map.get("$ref") {
                if let Some(key) = ["oneOf", "anyOf", "allOf"]
                    .into_iter()
                    .find(|key| map.contains_key(*key))
                {
                    return Err(format!(
                        "`$ref` beside `{key}` is unsupported; sibling constraints would be dropped"
                    ));
                }
                return reference_type(reference);
            }
            if let Some(value) = map.get("const") {
                return literal(value);
            }
            if let Some(values) = map.get("enum") {
                let values = values
                    .as_array()
                    .ok_or_else(|| "`enum` must be an array".to_string())?;
                let mut rendered = Vec::new();
                for value in values {
                    rendered.push(literal(value)?);
                }
                if rendered.is_empty() {
                    return Err("`enum` must not be empty".to_string());
                }
                return Ok(rendered.join(" | "));
            }
            let combinators: Vec<&str> = ["oneOf", "anyOf", "allOf"]
                .into_iter()
                .filter(|key| map.contains_key(*key))
                .collect();
            if combinators.len() > 1 {
                return Err(format!("schema mixes {}", combinators.join(" and ")));
            }
            if let Some(key) = combinators.first() {
                let values = map[*key]
                    .as_array()
                    .ok_or_else(|| format!("`{key}` must be an array"))?;
                if values.is_empty() {
                    return Err(format!("`{key}` must not be empty"));
                }
                let mut rendered = Vec::new();
                for value in values {
                    rendered.push(type_expr(value, indent)?);
                }
                let separator = if *key == "allOf" { " & " } else { " | " };
                let combined = join_types(rendered, separator, indent);
                let Some(sibling) = combinator_siblings(map, key)? else {
                    return Ok(combined);
                };
                let sibling = type_expr(&sibling, indent)?;
                return Ok(if *key == "allOf" {
                    format!("{combined} & {sibling}")
                } else {
                    format!("{} & {sibling}", parenthesize(&combined))
                });
            }
            match map.get("type") {
                Some(Value::String(kind)) => primitive(kind, map, indent),
                Some(Value::Array(kinds)) => {
                    let mut rendered = Vec::new();
                    for kind in kinds {
                        let kind = kind
                            .as_str()
                            .ok_or_else(|| "`type` array entries must be strings".to_string())?;
                        rendered.push(primitive(kind, map, indent)?);
                    }
                    if rendered.is_empty() {
                        return Err("`type` array must not be empty".to_string());
                    }
                    return Ok(join_types(rendered, " | ", indent));
                }
                Some(other) => return Err(format!("unsupported `type` value {other}")),
                None => {
                    if map.contains_key("properties") || map.contains_key("additionalProperties") {
                        return object_type(map, indent);
                    }
                    return Ok("unknown".to_string());
                }
            }
        }
        _ => Err("schema must be an object or a boolean".to_string()),
    }
}

/// Structural constraints sitting beside a combinator in the same schema node.
///
/// JSON Schema applies keywords beside `allOf`, `anyOf` and `oneOf` to the
/// same instance, so rendering only the combinator would silently drop
/// constraints such as `SerializedItem.activationSteps`. Returns `None` when
/// the node carries no sibling constraint.
fn combinator_siblings(
    map: &serde_json::Map<String, Value>,
    combinator: &str,
) -> Result<Option<Value>, String> {
    const NON_STRUCTURAL: &[&str] = &[
        "$schema",
        "$defs",
        "title",
        "description",
        "examples",
        "default",
        "deprecated",
        "readOnly",
        "writeOnly",
        "format",
        "minimum",
        "maximum",
        "exclusiveMinimum",
        "exclusiveMaximum",
        "multipleOf",
        "minLength",
        "maxLength",
        "pattern",
        "oneOf",
        "anyOf",
        "allOf",
    ];
    let mut siblings = serde_json::Map::new();
    for (key, value) in map {
        if NON_STRUCTURAL.contains(&key.as_str()) {
            continue;
        }
        if key == "type" {
            if value == "object" {
                continue;
            }
            return Err(format!("unsupported `type` {value} beside `{combinator}`"));
        }
        if !matches!(
            key.as_str(),
            "properties" | "required" | "additionalProperties"
        ) {
            return Err(format!("unsupported `{key}` beside `{combinator}`"));
        }
        siblings.insert(key.clone(), value.clone());
    }
    if siblings.is_empty() {
        return Ok(None);
    }
    Ok(Some(Value::Object(siblings)))
}

/// Render one primitive JSON Schema type, delegating compound shapes.
fn primitive(
    kind: &str,
    map: &serde_json::Map<String, Value>,
    indent: usize,
) -> Result<String, String> {
    match kind {
        "object" => object_type(map, indent),
        "array" => {
            let items = map
                .get("items")
                .ok_or_else(|| "arrays require `items`; tuples are unsupported".to_string())?;
            let item = type_expr(items, indent)?;
            Ok(format!("{}[]", parenthesize(&item)))
        }
        "string" => Ok("string".to_string()),
        "integer" | "number" => Ok("number".to_string()),
        "boolean" => Ok("boolean".to_string()),
        "null" => Ok("null".to_string()),
        other => Err(format!("unsupported JSON Schema type {other:?}")),
    }
}

/// Render an object type with optionality and index signatures.
fn object_type(map: &serde_json::Map<String, Value>, indent: usize) -> Result<String, String> {
    let properties = map.get("properties").and_then(Value::as_object);
    let additional = map.get("additionalProperties");
    let required: BTreeSet<&str> = map
        .get("required")
        .map(|value| {
            value
                .as_array()
                .ok_or_else(|| "`required` must be an array".to_string())?
                .iter()
                .map(|name| {
                    name.as_str()
                        .ok_or_else(|| "`required` entries must be strings".to_string())
                })
                .collect()
        })
        .transpose()?
        .unwrap_or_default();

    let has_properties = properties.map_or(false, |properties| !properties.is_empty());
    let has_additional = matches!(additional, Some(Value::Bool(true)) | Some(Value::Object(_)));
    if !has_properties && !has_additional {
        return Ok("Record<string, never>".to_string());
    }

    let pad = " ".repeat(indent + 2);
    let mut out = String::from("{\n");
    if let Some(properties) = properties {
        let sorted: BTreeMap<&String, &Value> = properties.iter().collect();
        for (name, property) in sorted {
            if let Some(doc) = doc_comment(property, indent + 2) {
                out.push_str(&doc);
            }
            let optional = if required.contains(name.as_str()) {
                ""
            } else {
                "?"
            };
            out.push_str(&format!(
                "{pad}{}{optional}: {};\n",
                property_name(name),
                type_expr(property, indent + 2)?
            ));
        }
    }
    match additional {
        None | Some(Value::Bool(false)) => {}
        Some(Value::Bool(true)) => out.push_str(&format!("{pad}[key: string]: unknown;\n")),
        Some(schema @ Value::Object(_)) => out.push_str(&format!(
            "{pad}[key: string]: {};\n",
            type_expr(schema, indent + 2)?
        )),
        Some(other) => return Err(format!("unsupported `additionalProperties` value {other}")),
    }
    out.push_str(&" ".repeat(indent));
    out.push('}');
    Ok(out)
}

/// Join union or intersection members, breaking lines for compound shapes.
fn join_types(members: Vec<String>, separator: &str, indent: usize) -> String {
    if members.len() > 1 && members.iter().any(|member| member.contains('\n')) {
        let member_separator = if separator.contains('&') {
            format!("\n{}& ", " ".repeat(indent))
        } else {
            format!("\n{}| ", " ".repeat(indent))
        };
        members.join(&member_separator)
    } else {
        members.join(separator)
    }
}

/// Parenthesize a type expression before appending `[]`.
fn parenthesize(expression: &str) -> String {
    if expression.contains(" | ") || expression.contains(" & ") {
        format!("({expression})")
    } else {
        expression.to_string()
    }
}

/// Validate a `$ref` and render its local type name.
fn reference_type(value: &Value) -> Result<String, String> {
    let reference = value
        .as_str()
        .ok_or_else(|| "`$ref` must be a string".to_string())?;
    if reference == "#" {
        return Ok("Root".to_string());
    }
    let name = reference
        .strip_prefix("#/$defs/")
        .ok_or_else(|| format!("unsupported `$ref` {reference:?}"))?;
    if name.contains('/') {
        return Err(format!("unsupported nested `$ref` {reference:?}"));
    }
    validate_identifier(name)?;
    Ok(name.to_string())
}

/// Render a literal const or enum member.
fn literal(value: &Value) -> Result<String, String> {
    match value {
        Value::String(text) => Ok(serde_json::to_string(text).expect("string serializes")),
        Value::Bool(flag) => Ok(flag.to_string()),
        Value::Number(number) => Ok(number.to_string()),
        Value::Null => Ok("null".to_string()),
        other => Err(format!("unsupported const/enum value {other}")),
    }
}

/// Quote a property name unless it is a plain TypeScript identifier.
fn property_name(name: &str) -> String {
    if validate_identifier(name).is_ok() {
        name.to_string()
    } else {
        serde_json::to_string(name).expect("property name serializes")
    }
}

/// Render a JSDoc block for a schema's description and annotations.
fn doc_comment(schema: &Value, indent: usize) -> Option<String> {
    let map = schema.as_object()?;
    let description = map.get("description").and_then(Value::as_str);
    let annotations = annotations(map);
    if description.is_none() && annotations.is_empty() {
        return None;
    }
    let pad = " ".repeat(indent);
    let mut out = format!("{pad}/**\n");
    if let Some(description) = description {
        for line in description.replace("*/", "* /").lines() {
            out.push_str(&format!("{pad} * {line}\n"));
        }
    }
    for annotation in annotations {
        out.push_str(&format!("{pad} * {annotation}\n"));
    }
    out.push_str(&format!("{pad} */\n"));
    Some(out)
}

/// Annotation-only JSON Schema constraints preserved as JSDoc tags.
fn annotations(map: &serde_json::Map<String, Value>) -> Vec<String> {
    let mut out = Vec::new();
    for key in [
        "format",
        "minimum",
        "maximum",
        "exclusiveMinimum",
        "exclusiveMaximum",
        "multipleOf",
        "minLength",
        "maxLength",
        "pattern",
    ] {
        if let Some(value) = map.get(key) {
            let rendered = if key == "format" {
                value
                    .as_str()
                    .map(str::to_string)
                    .unwrap_or_else(|| value.to_string())
            } else {
                value.to_string()
            };
            out.push(format!("@{key} {rendered}"));
        }
    }
    if let Some(value) = map.get("default") {
        out.push(format!("@default {}", value));
    }
    if map.get("deprecated") == Some(&Value::Bool(true)) {
        out.push("@deprecated".to_string());
    }
    out
}

/// Reject schema keywords this generator cannot represent.
fn validate_keys(map: &serde_json::Map<String, Value>) -> Result<(), String> {
    const ALLOWED: &[&str] = &[
        "$schema",
        "$defs",
        "$ref",
        "title",
        "description",
        "type",
        "properties",
        "required",
        "additionalProperties",
        "items",
        "oneOf",
        "anyOf",
        "allOf",
        "const",
        "enum",
        "format",
        "minimum",
        "maximum",
        "exclusiveMinimum",
        "exclusiveMaximum",
        "multipleOf",
        "minLength",
        "maxLength",
        "pattern",
        "default",
        "examples",
        "deprecated",
        "readOnly",
        "writeOnly",
    ];
    for key in map.keys() {
        if !ALLOWED.contains(&key.as_str()) {
            return Err(format!("unsupported JSON Schema keyword `{key}`"));
        }
    }
    Ok(())
}

/// Validate that a generated identifier is a plain TypeScript identifier.
fn validate_identifier(name: &str) -> Result<(), String> {
    let mut chars = name.chars();
    match chars.next() {
        Some(first) if first.is_ascii_alphabetic() || first == '_' || first == '$' => {}
        _ => return Err(format!("{name:?} is not a valid TypeScript identifier")),
    }
    if chars
        .all(|character| character.is_ascii_alphanumeric() || character == '_' || character == '$')
    {
        Ok(())
    } else {
        Err(format!("{name:?} is not a valid TypeScript identifier"))
    }
}
